script.text:
			/* <flatten type="Javascript"> */
function load$Grid(g) {
	g.add_onResponseComplete(on$GridContract$ResponseComplete);
	g.add_commandEvent(on$GridContract$ExecuteCommand);
	g.add_onRender(on$GridContract$GridRender);
}
function dispose$Grid(g) {
	try {g.remove_commandEvent(on$GridContract$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridContract$ResponseComplete);} catch (ex) {}
	try {g.remove_onRender(on$GridContract$GridRender);} catch (ex) {}
}
function on$GridContract$GridRender(sender, eventArgs) {
	var g = eventArgs.grid;
	if (g._extensions && g._rowCount == 1) {
		g._setActiveCell(g._getItem(1, 1));
		g.executeCommand({commandName:'View',commandArgument:'0'})
	}
}
/* </flatten> */
function on$GridContract$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'ImportData':
			show$Form(g, 'zContract4Import');
			break;
		case 'Download':
			switch(e.type.Value) {
				case '05':
					&UserDefinedDownload;
				case '10':
					&UserDefinedDownloadExtension;
				case '15':
					var r = $get('requestFormData');
					if (!r) r = $func.requestFormData();
					var query = '?type=TemplateUpload&controller=zContract4&form=zContract4PaymentTL' + String.format('&r={0}', Math.random());
					r.action = $func.resolveClientUrl('~/AppHandler/ExportHandler.ashx' + query, g._baseUrl);
					if (!$func.isIE) r.target = '_blank';
					r.submit();
					break;
				case '20':
					var r = $get('requestFormData');
					if (!r) r = $func.requestFormData();
					var query = '?type=TemplateUpload&controller=zContract4&form=zContract4CTBL' + String.format('&r={0}', Math.random());
					r.action = $func.resolveClientUrl('~/AppHandler/ExportHandler.ashx' + query, g._baseUrl);
					if (!$func.isIE) r.target = '_blank';
					r.submit();
					break;
				case '41':
					var r = $get('requestFormData');
					if (!r) r = $func.requestFormData();
					var query = '?type=TemplateUpload&controller=zContract1&form=zContract4HisCustomer' + String.format('&r={0}', Math.random());
					r.action = $func.resolveClientUrl('~/AppHandler/ExportHandler.ashx' + query, g._baseUrl);
					if (!$func.isIE) r.target = '_blank';
					r.submit();
					break;
				default:break;
			}
			break;
			default:
				break;
	}
}
/* <flatten type="Javascript"> */
function on$GridContract$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object;
	switch (context) {
		case 'Download':
			g._key = result[0].Value;
			break;
		default:
			break;
	}
}
function show$Form(g, c) {(g._authorize == 1) ? g.showForm(c) : $message.show($df.getResources(g._language, "Message.NotAccess"));}
/* </flatten> */
			&DowloadScript;
